-- =====================================================================
-- 487_tprm_baseline_seed.sql
--
-- REQUEST (2026-10-24)
-- --------------------
--   TPRM BRD section 5: "GRAC must ship with a usable baseline TPRM
--   template library rather than an empty module." This is Layer 1 (GRAC
--   baseline) for every configuration type 486 created:
--     5.1-1  third-party classification   SERVICE_CATEGORY, PROVIDER_TYPE,
--                                          CRITICALITY, TP_STATUS
--     5.1-2  engagement classification    SERVICE_MODEL, ENGAGEMENT_TYPE,
--                                          DATA_EXPOSURE, ACCESS_CATEGORY
--     5.1-3  risk assessment              risk model GRAC_TPRM_STANDARD v1:
--                                          the eight BRD dimensions, factors,
--                                          options, scores, bands, DD tiers,
--                                          tier rules
--     5.1-4  due-diligence questionnaires core + enhanced + six
--                                          service-specific sets with
--                                          conditional follow-ups
--     5.1-5  safeguard library            contractual, operational,
--                                          security, privacy, resilience,
--                                          regulatory
--     5.1-6  evidence requirements        types, validity, review
--     5.1-7  risk treatment               common actions with due days
--     5.1-8  approval rules               four baseline paths
--     5.1-9  monitoring and review        four review rules, triggers,
--                                          onboarding and exit checks
--     5.1-10 fourth-party assessment      FOURTH_PARTY_CATEGORY + the
--                                          fourth-party dimension, factors
--                                          and questions
--     5.2    sample records               six illustrative profiles
--                                          (tprm_sample_profile); 488's
--                                          sp_tprm_sample_load creates them
--                                          in an organization, flagged as
--                                          samples, never as completed
--                                          assessments.
--
-- PROVENANCE (BRD 5.3)
-- --------------------
--   Every baseline row is GRAC's own illustrative content:
--   source_authority 'GRAC baseline (illustrative)', is_regulatory = 0.
--   Related standards are cited in source_reference as "informative"
--   only -- nothing here is presented as a mandatory regulatory
--   requirement. An organization that maps a row to a regulation does so
--   on its own copy with the source and applicability it has established.
--
-- RE-RUNNING
-- ----------
--   Lists and library rows: MERGE on the code, baseline rows only; an
--   organization's overrides are never touched. Templates: inserted only
--   when the baseline template does not exist -- a published version is
--   never rewritten. A later baseline change ships as a NEW version in a
--   new migration; organizations see "update available" and adopt it.
--
-- Generated by tools/tprm/gen_487.py. DEPENDS ON: 486.
-- Rollback: 487_tprm_baseline_seed_rollback.sql
-- ASCII-only.
-- =====================================================================
SET NOCOUNT ON;
SET XACT_ABORT ON;
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
SET NOEXEC OFF;
GO

IF OBJECT_ID('grac_practice.tprm_template_version','U') IS NULL
   OR OBJECT_ID('grac_practice.tprm_reference_value','U') IS NULL
BEGIN
    RAISERROR('ABORT (487): run 486_tprm_configuration.sql first.', 16, 1);
    SET NOEXEC ON;
END
GO

-- =====================================================================
-- 0. Sample profile table (baseline content of BRD 5.2)
-- =====================================================================
IF OBJECT_ID('grac_practice.tprm_sample_profile','U') IS NULL
BEGIN
    CREATE TABLE grac_practice.tprm_sample_profile(
        sample_code           NVARCHAR(60)   NOT NULL CONSTRAINT pk_pm_tprm_sample_profile PRIMARY KEY,
        legal_name            NVARCHAR(250)  NOT NULL,
        provider_type_code    NVARCHAR(60)   NOT NULL,
        service_category_code NVARCHAR(60)   NOT NULL,
        country               NVARCHAR(120)  NULL,
        engagement_title      NVARCHAR(250)  NOT NULL,
        service_description   NVARCHAR(2000) NOT NULL,
        scope_description     NVARCHAR(2000) NULL,
        business_purpose      NVARCHAR(1000) NULL,
        service_model_code    NVARCHAR(60)   NULL,
        engagement_type_code  NVARCHAR(60)   NULL,
        criticality_code      NVARCHAR(60)   NULL,
        data_exposure_code    NVARCHAR(60)   NULL,
        access_codes          NVARCHAR(400)  NULL,
        rto_hours             INT            NULL,
        rpo_hours             INT            NULL,
        fourth_parties        NVARCHAR(1000) NULL,   -- name|FOURTH_PARTY_CATEGORY|country;...
        key_safeguards        NVARCHAR(1000) NULL,   -- safeguard codes
        evidence_expectations NVARCHAR(1000) NULL,   -- evidence requirement codes
        review_triggers       NVARCHAR(1000) NULL,   -- REVIEW_TRIGGER codes
        notes                 NVARCHAR(2000) NULL,
        display_order         INT            NOT NULL CONSTRAINT df_pm_tprm_sp_order DEFAULT 100
    );
    PRINT '487: tprm_sample_profile created.';
END
GO

