WHEN MATCHED THEN UPDATE SET list_name = s.list_name, description = s.description, scope_rule = s.scope_rule,
    allowed_meanings = s.allowed_meanings, display_order = s.display_order, updated_by = N'seed-487', updated_dt = SYSUTCDATETIME()
WHEN NOT MATCHED THEN INSERT (list_code, list_name, description, scope_rule, allowed_meanings, display_order, entered_by)
    VALUES (s.list_code, s.list_name, s.description, s.scope_rule, s.allowed_meanings, s.display_order, N'seed-487');
PRINT CONCAT('487: reference lists merged: ', @@ROWCOUNT);
GO

