    is_contract_clause = s.is_contract_clause, evidence_requirement_code = s.evidence_requirement_code,
    validity_months = s.validity_months, review_required = s.review_required, default_due_days = s.default_due_days,
    default_owner_hint = s.default_owner_hint, source_authority = s.source_authority, source_document = s.source_document,
    source_version = s.source_version, source_reference = s.source_reference, applicability_note = s.applicability_note,
    is_regulatory = s.is_regulatory, display_order = s.display_order, status = N'Active',
    updated_by = N'seed-487', updated_dt = SYSUTCDATETIME()
WHEN NOT MATCHED BY TARGET THEN INSERT
    (library_code, organization_id, item_code, item_name, description, category_code, dimension_code, guidance, effectiveness_criteria,
     is_contract_clause, evidence_requirement_code, validity_months, review_required, default_due_days, default_owner_hint,
     source_authority, source_document, source_version, source_reference, applicability_note, is_regulatory, display_order, status, entered_by)
    VALUES (s.library_code, NULL, s.item_code, s.item_name, s.description, s.category_code, s.dimension_code, s.guidance, s.effectiveness_criteria,
     s.is_contract_clause, s.evidence_requirement_code, s.validity_months, s.review_required, s.default_due_days, s.default_owner_hint,
     s.source_authority, s.source_document, s.source_version, s.source_reference, s.applicability_note, s.is_regulatory, s.display_order,
     N'Active', N'seed-487');
PRINT CONCAT('487: library items merged: ', @@ROWCOUNT);
GO

-- =====================================================================
-- 4. Approval rules and review rules
--    Role names are matched against organization_role.role_name of the
--    organization. When the organization has no role of that name, any
--    person holding APPROVE on Engagements may act at that level
--    (segregation of duties still applies) -- docs/tprm.md D7.
-- =====================================================================
MERGE grac_practice.tprm_approval_rule AS t
USING (VALUES
    (N'AR_CRITICAL', N'Critical residual risk or critical service', N'Three-level approval with escalation to the Risk Centre.', 10, 4, 4, 3, N'TPRM Approver', N'Risk Reviewer', N'Chief Risk Officer', 1, 1, 6, NULL),
    (N'AR_HIGH', N'High residual risk or high criticality', N'Two-level approval.', 20, 3, 3, 2, N'TPRM Approver', N'Risk Reviewer', NULL, 1, 0, 12, NULL),
    (N'AR_MODERATE', N'Moderate residual risk', N'Single approval by the TPRM approver.', 30, 2, NULL, 1, N'TPRM Approver', NULL, NULL, 1, 0, 24, NULL),
    (N'AR_LOW', N'Low residual risk', N'Single approval by the TPRM approver.', 90, NULL, NULL, 1, N'TPRM Approver', NULL, NULL, 1, 0, 36, NULL)
) AS s(rule_code, rule_name, description, priority, min_band_rank, min_criticality_rank, approval_levels, level1_role_name,
       level2_role_name, level3_role_name, sod_required, escalate_to_risk_centre, max_acceptance_months, allowed_decision_codes)
ON t.organization_id IS NULL AND t.rule_code = s.rule_code
WHEN MATCHED THEN UPDATE SET rule_name = s.rule_name, description = s.description, priority = s.priority,
    min_band_rank = s.min_band_rank, min_criticality_rank = s.min_criticality_rank, approval_levels = s.approval_levels,
    level1_role_name = s.level1_role_name, level2_role_name = s.level2_role_name, level3_role_name = s.level3_role_name,
    sod_required = s.sod_required, escalate_to_risk_centre = s.escalate_to_risk_centre,
    max_acceptance_months = s.max_acceptance_months, allowed_decision_codes = s.allowed_decision_codes,
    status = N'Active', updated_by = N'seed-487', updated_dt = SYSUTCDATETIME()
WHEN NOT MATCHED BY TARGET THEN INSERT
    (organization_id, rule_code, rule_name, description, priority, min_band_rank, min_criticality_rank, approval_levels, level1_role_name,
     level2_role_name, level3_role_name, sod_required, escalate_to_risk_centre, max_acceptance_months, allowed_decision_codes, status, entered_by)
    VALUES (NULL, s.rule_code, s.rule_name, s.description, s.priority, s.min_band_rank, s.min_criticality_rank, s.approval_levels,
     s.level1_role_name, s.level2_role_name, s.level3_role_name, s.sod_required, s.escalate_to_risk_centre, s.max_acceptance_months,
     s.allowed_decision_codes, N'Active', N'seed-487');
PRINT CONCAT('487: approval rules merged: ', @@ROWCOUNT);
GO

MERGE grac_practice.tprm_review_rule AS t
USING (VALUES
    (N'RR_CRITICAL', N'Critical: six-monthly review', N'Six-monthly review; evidence renewed yearly.', 10, 4, 4, 6, 12, 120, 90, 30, N'INCIDENT,MATERIAL_CHANGE,SCOPE_CHANGE,DATA_ACCESS_CHANGE,LOCATION_CHANGE,FOURTH_PARTY_CHANGE,SLA_BREACH,ASSURANCE_FAILURE,OVERDUE_REMEDIATION,ACCEPTANCE_EXPIRY', N'Quarterly service and security reporting expected.'),
    (N'RR_HIGH', N'High: annual review', N'Annual review; evidence renewed yearly.', 20, 3, 3, 12, 12, 90, 60, 30, N'INCIDENT,MATERIAL_CHANGE,SCOPE_CHANGE,DATA_ACCESS_CHANGE,LOCATION_CHANGE,FOURTH_PARTY_CHANGE,SLA_BREACH,ASSURANCE_FAILURE,OVERDUE_REMEDIATION,ACCEPTANCE_EXPIRY', N'Six-monthly service reporting expected.'),
    (N'RR_MODERATE', N'Moderate: review every two years', N'Review every 24 months.', 30, 2, NULL, 24, 24, 60, 45, 30, N'INCIDENT,MATERIAL_CHANGE,SCOPE_CHANGE,DATA_ACCESS_CHANGE,ACCEPTANCE_EXPIRY', NULL),
    (N'RR_LOW', N'Low: review every three years', N'Review every 36 months.', 90, NULL, NULL, 36, 36, 45, 30, 30, N'INCIDENT,MATERIAL_CHANGE,ACCEPTANCE_EXPIRY', NULL)
) AS s(rule_code, rule_name, description, priority, min_band_rank, min_criticality_rank, review_frequency_months,
       evidence_renewal_months, contract_expiry_alert_days, cert_expiry_alert_days, review_lead_days, reassessment_trigger_codes, monitoring_note)
ON t.organization_id IS NULL AND t.rule_code = s.rule_code
WHEN MATCHED THEN UPDATE SET rule_name = s.rule_name, description = s.description, priority = s.priority,
    min_band_rank = s.min_band_rank, min_criticality_rank = s.min_criticality_rank, review_frequency_months = s.review_frequency_months,
    evidence_renewal_months = s.evidence_renewal_months, contract_expiry_alert_days = s.contract_expiry_alert_days,
    cert_expiry_alert_days = s.cert_expiry_alert_days, review_lead_days = s.review_lead_days,
    reassessment_trigger_codes = s.reassessment_trigger_codes, monitoring_note = s.monitoring_note,
    status = N'Active', updated_by = N'seed-487', updated_dt = SYSUTCDATETIME()
WHEN NOT MATCHED BY TARGET THEN INSERT
    (organization_id, rule_code, rule_name, description, priority, min_band_rank, min_criticality_rank, review_frequency_months,
     evidence_renewal_months, contract_expiry_alert_days, cert_expiry_alert_days, review_lead_days, reassessment_trigger_codes,
     monitoring_note, status, entered_by)
    VALUES (NULL, s.rule_code, s.rule_name, s.description, s.priority, s.min_band_rank, s.min_criticality_rank, s.review_frequency_months,
     s.evidence_renewal_months, s.contract_expiry_alert_days, s.cert_expiry_alert_days, s.review_lead_days, s.reassessment_trigger_codes,
     s.monitoring_note, N'Active', N'seed-487');
PRINT CONCAT('487: review rules merged: ', @@ROWCOUNT);
GO

-- =====================================================================
-- 5. Risk model GRAC_TPRM_STANDARD v1 (the BRD step 2 dimensions)
--    Dimension score = average over its factors of (score / highest
--    option score) x 100. Overall = BLENDED: 40% highest dimension + 60%
--    weighted average, so one severe dimension is not averaged away.
-- =====================================================================
IF NOT EXISTS (SELECT 1 FROM grac_practice.tprm_template
                WHERE organization_id IS NULL AND template_kind = N'RISK_MODEL' AND template_code = N'GRAC_TPRM_STANDARD')
BEGIN
    DECLARE @t BIGINT, @v BIGINT;
    BEGIN TRAN;
    INSERT grac_practice.tprm_template (organization_id, template_kind, template_code, template_name, description, is_default, status, entered_by)
    VALUES (NULL, N'RISK_MODEL', N'GRAC_TPRM_STANDARD', N'GRAC standard engagement risk model',
            N'Eight inherent-risk dimensions from the TPRM BRD with weighted factors, four risk bands and due-diligence tiers. Illustrative baseline - calibrate before relying on it.',
            1, N'Active', N'seed-487');
    SET @t = SCOPE_IDENTITY();
    INSERT grac_practice.tprm_template_version
        (template_id, version_no, status, change_summary, aggregation_method, blend_pct, effective_reduction_pct,
         partial_reduction_pct, residual_floor_pct, deficiency_uplift_pct, created_by, activated_by, activated_dt)
    VALUES (@t, 1, N'ACTIVE', N'GRAC baseline version 1', N'BLENDED', 40, 60, 30, 20, 10, N'seed-487', N'seed-487', SYSUTCDATETIME());
    SET @v = SCOPE_IDENTITY();
    UPDATE grac_practice.tprm_template SET current_version_id = @v WHERE template_id = @t;

    INSERT grac_practice.tprm_rm_dimension (version_id, dimension_code, dimension_name, description, weight, display_order)
    SELECT @v, x.c, x.n, x.d, x.w, x.o FROM (VALUES
        (N'SERVICE_CRITICALITY', N'Service criticality and business impact', N'Impact on operations, customers and obligations if the service fails.', 20, 10),
        (N'DATA_ACCESS', N'Data sensitivity and access exposure', N'Sensitivity and volume of data, and the access the third party has.', 20, 20),
        (N'TECH_CYBER', N'Technology and cybersecurity exposure', N'Technology delivery, integration and change exposure.', 15, 30),
        (N'REGULATORY', N'Regulatory and contractual obligations', N'Regulation and contractual commitments that depend on the service.', 10, 40),
        (N'TP_CAPABILITY', N'Third-party capability and organizational profile', N'Maturity, financial strength and track record of the third party.', 10, 50),
        (N'FOURTH_PARTY', N'Fourth-party and concentration risk', N'Reliance on subcontractors and concentration on the third party.', 10, 60),
        (N'GEOGRAPHIC', N'Geographic and jurisdictional exposure', N'Where the service is delivered and data is processed.', 5, 70),
        (N'EXIT', N'Substitutability and exit complexity', N'How hard the service is to replace or exit.', 10, 80)
    ) x(c, n, d, w, o);
    INSERT grac_practice.tprm_rm_factor (version_id, dimension_id, factor_code, question_text, guidance, is_mandatory, prefill_source, display_order)
    SELECT @v, d.dimension_id, x.c, x.t, x.g, 1, x.p, x.o FROM (VALUES
        (N'SERVICE_CRITICALITY', N'SC_CRITICALITY', N'How critical is the service to the organization''s operations?', NULL, N'SERVICE_CRITICALITY', 10),
        (N'SERVICE_CRITICALITY', N'SC_OUTAGE', N'What would a 24-hour outage of the service cause?', NULL, NULL, 20),
        (N'SERVICE_CRITICALITY', N'SC_CUSTOMER', N'Does the service support a customer-facing or regulated process?', NULL, NULL, 30),
        (N'DATA_ACCESS', N'DA_DATA', N'Most sensitive data the third party will store, process or access', NULL, N'DATA_EXPOSURE', 40),
        (N'DATA_ACCESS', N'DA_ACCESS', N'Highest access to the organization''s systems, networks or premises', NULL, N'ACCESS', 50),
        (N'DATA_ACCESS', N'DA_VOLUME', N'Volume of records or individuals in scope', NULL, NULL, 60),
        (N'TECH_CYBER', N'TC_MODEL', N'How is the service delivered?', NULL, N'SERVICE_MODEL', 70),
        (N'TECH_CYBER', N'TC_INTEGRATION', N'Does the service connect to the organization''s network or core systems?', NULL, NULL, 80),
        (N'TECH_CYBER', N'TC_CHANGE', N'Does the third party build or change software the organization uses?', NULL, NULL, 90),
        (N'REGULATORY', N'RG_REGULATED', N'Is the service subject to outsourcing, sectoral or data-protection regulation?', NULL, NULL, 100),
        (N'REGULATORY', N'RG_CONTRACTUAL', N'Do commitments to customers or partners depend on this service?', NULL, NULL, 110),
        (N'TP_CAPABILITY', N'TP_MATURITY', N'How established is the third party?', NULL, NULL, 120),
        (N'TP_CAPABILITY', N'TP_FINANCIAL', N'Financial stability of the third party', NULL, NULL, 130),
        (N'TP_CAPABILITY', N'TP_HISTORY', N'Relationship history', NULL, N'IS_EXISTING', 140),
        (N'FOURTH_PARTY', N'FP_COUNT', N'Material subcontractors / fourth parties used for the service', NULL, N'FOURTH_PARTY_COUNT', 150),
        (N'FOURTH_PARTY', N'FP_CONCENTRATION', N'How many other critical services already depend on this third party or its key fourth parties?', NULL, NULL, 160),
        (N'GEOGRAPHIC', N'GE_LOCATION', N'Where is the service delivered or data processed?', NULL, NULL, 170),
        (N'EXIT', N'EX_SUBSTITUTE', N'How easily could the service be replaced?', NULL, NULL, 180),
        (N'EXIT', N'EX_DURATION', N'Time needed to exit and transition', NULL, NULL, 190)
    ) x(dc, c, t, g, p, o)
    JOIN grac_practice.tprm_rm_dimension d ON d.version_id = @v AND d.dimension_code = x.dc;
    INSERT grac_practice.tprm_rm_factor_option (factor_id, option_code, option_label, score, prefill_match_code, display_order)
    SELECT f.factor_id, x.c, x.l, x.s, x.m, x.o FROM (VALUES
        (N'SC_CRITICALITY', N'LOW', N'Low - inconvenient if unavailable', 0, N'LOW', 10),
        (N'SC_CRITICALITY', N'MEDIUM', N'Medium - workarounds exist', 1, N'MEDIUM', 20),
        (N'SC_CRITICALITY', N'HIGH', N'High - key process affected', 3, N'HIGH', 30),
        (N'SC_CRITICALITY', N'CRITICAL', N'Critical - core or regulated operation stops', 4, N'CRITICAL', 40),
        (N'SC_OUTAGE', N'MINIMAL', N'Minimal impact', 0, NULL, 10),
        (N'SC_OUTAGE', N'MODERATE', N'Moderate disruption', 2, NULL, 20),
        (N'SC_OUTAGE', N'SEVERE', N'Severe disruption or customer impact', 3, NULL, 30),
        (N'SC_OUTAGE', N'BREACH', N'Regulatory breach or major customer harm', 4, NULL, 40),
        (N'SC_CUSTOMER', N'NO', N'No - internal support only', 0, NULL, 10),
        (N'SC_CUSTOMER', N'INTERNAL', N'Internal but business-critical', 2, NULL, 20),
        (N'SC_CUSTOMER', N'CUSTOMER', N'Customer-facing', 3, NULL, 30),
        (N'SC_CUSTOMER', N'REGULATED', N'Customer-facing and regulated', 4, NULL, 40),
        (N'DA_DATA', N'NONE', N'No organization data', 0, N'NONE', 10),
        (N'DA_DATA', N'INTERNAL', N'Internal', 1, N'INTERNAL', 20),
        (N'DA_DATA', N'CONFIDENTIAL', N'Confidential business data', 2, N'CONFIDENTIAL', 30),
        (N'DA_DATA', N'PERSONAL', N'Personal data', 3, N'PERSONAL', 40),
        (N'DA_DATA', N'SENSITIVE', N'Sensitive personal, payment or regulated financial data', 4, N'SENSITIVE_PERSONAL,PAYMENT,REGULATED_FINANCIAL', 50),
        (N'DA_ACCESS', N'NONE', N'No access', 0, N'NONE', 10),
        (N'DA_ACCESS', N'PHYSICAL', N'Physical access only', 1, N'PHYSICAL', 20),
        (N'DA_ACCESS', N'REMOTE', N'Remote user access', 2, N'REMOTE_USER', 30),
        (N'DA_ACCESS', N'INTEGRATION', N'System integration or network connectivity', 3, N'SYSTEM_INTEGRATION,NETWORK', 40),
        (N'DA_ACCESS', N'PRIVILEGED', N'Privileged access or hosts organization data', 4, N'PRIVILEGED,DATA_HOSTING', 50),
        (N'DA_VOLUME', N'NEGLIGIBLE', N'None or negligible', 0, NULL, 10),
        (N'DA_VOLUME', N'SMALL', N'Fewer than 10,000', 1, NULL, 20),
        (N'DA_VOLUME', N'LARGE', N'10,000 to 1,000,000', 3, NULL, 30),
        (N'DA_VOLUME', N'VERY_LARGE', N'More than 1,000,000', 4, NULL, 40),
        (N'TC_MODEL', N'ONSITE', N'Onsite staff / on-premise under the organization''s control', 1, N'ON_PREMISE,ONSITE_STAFF', 10),
        (N'TC_MODEL', N'REMOTE', N'Offshore or remote delivery', 2, N'OFFSHORE', 20),
        (N'TC_MODEL', N'MANAGED', N'Managed service, SaaS, PaaS or hybrid', 3, N'MANAGED_SERVICE,SAAS,PAAS,HYBRID', 30),
        (N'TC_MODEL', N'INFRA', N'Infrastructure hosting (IaaS)', 4, N'IAAS', 40),
        (N'TC_INTEGRATION', N'NO', N'No connection', 0, NULL, 10),
        (N'TC_INTEGRATION', N'ONE_WAY', N'Limited one-way file exchange', 2, NULL, 20),
        (N'TC_INTEGRATION', N'API', N'Two-way / API integration', 3, NULL, 30),
        (N'TC_INTEGRATION', N'NETWORK', N'Direct network connectivity', 4, NULL, 40),
        (N'TC_CHANGE', N'NO', N'No', 0, NULL, 10),
        (N'TC_CHANGE', N'CONFIG', N'Configuration only', 1, NULL, 20),
        (N'TC_CHANGE', N'CUSTOM', N'Custom development', 3, NULL, 30),
        (N'TC_CHANGE', N'CORE', N'Development of core systems', 4, NULL, 40),
        (N'RG_REGULATED', N'NO', N'No', 0, NULL, 10),
        (N'RG_REGULATED', N'SOME', N'Some requirements apply', 2, NULL, 20),
        (N'RG_REGULATED', N'MATERIAL', N'Material outsourcing or regulator notification needed', 4, NULL, 30),
        (N'RG_CONTRACTUAL', N'NO', N'No', 0, NULL, 10),
        (N'RG_CONTRACTUAL', N'SOME', N'Some', 2, NULL, 20),
        (N'RG_CONTRACTUAL', N'SIGNIFICANT', N'Significant', 4, NULL, 30),
        (N'TP_MATURITY', N'ESTABLISHED', N'More than 10 years in operation', 0, NULL, 10),
        (N'TP_MATURITY', N'MATURE', N'5 to 10 years', 1, NULL, 20),
        (N'TP_MATURITY', N'GROWING', N'2 to 5 years', 2, NULL, 30),
        (N'TP_MATURITY', N'STARTUP', N'Less than 2 years / start-up', 4, NULL, 40),
        (N'TP_FINANCIAL', N'STRONG', N'Strong', 0, NULL, 10),
        (N'TP_FINANCIAL', N'ADEQUATE', N'Adequate', 1, NULL, 20),
        (N'TP_FINANCIAL', N'UNCERTAIN', N'Uncertain', 3, NULL, 30),
        (N'TP_FINANCIAL', N'WEAK', N'Weak or unknown', 4, NULL, 40),
        (N'TP_HISTORY', N'GOOD', N'Existing relationship with good performance', 0, N'YES', 10),
        (N'TP_HISTORY', N'NEW', N'New third party', 2, N'NO', 20),
        (N'TP_HISTORY', N'ISSUES', N'Existing relationship with performance or compliance issues', 4, NULL, 30),
        (N'FP_COUNT', N'NONE', N'None', 0, N'0', 10),
        (N'FP_COUNT', N'FEW', N'One or two', 2, N'1,2', 20),
        (N'FP_COUNT', N'MANY', N'Three or more', 4, N'3+', 30),
        (N'FP_CONCENTRATION', N'NONE', N'None', 0, NULL, 10),
        (N'FP_CONCENTRATION', N'ONE', N'One', 2, NULL, 20),
        (N'FP_CONCENTRATION', N'SEVERAL', N'Several', 4, NULL, 30),
        (N'GE_LOCATION', N'DOMESTIC', N'In the organization''s country only', 0, NULL, 10),
        (N'GE_LOCATION', N'ADEQUATE', N'Multiple countries with adequate protection', 2, NULL, 20),
        (N'GE_LOCATION', N'RESTRICTED', N'Jurisdictions with transfer restrictions or elevated risk', 4, NULL, 30),
        (N'EX_SUBSTITUTE', N'EASY', N'Readily available alternatives', 0, NULL, 10),
        (N'EX_SUBSTITUTE', N'EFFORT', N'Alternatives with some effort', 2, NULL, 20),
        (N'EX_SUBSTITUTE', N'DIFFICULT', N'Few alternatives', 3, NULL, 30),
        (N'EX_SUBSTITUTE', N'NONE', N'Not substitutable', 4, NULL, 40),
        (N'EX_DURATION', N'SHORT', N'Less than 3 months', 0, NULL, 10),
        (N'EX_DURATION', N'MEDIUM', N'3 to 6 months', 1, NULL, 20),
        (N'EX_DURATION', N'LONG', N'6 to 12 months', 3, NULL, 30),
        (N'EX_DURATION', N'VERY_LONG', N'More than 12 months', 4, NULL, 40)
    ) x(fc, c, l, s, m, o)
    JOIN grac_practice.tprm_rm_factor f ON f.version_id = @v AND f.factor_code = x.fc;
    INSERT grac_practice.tprm_rm_band (version_id, band_code, band_name, min_score, rank_no, color_hex, dd_tier_code)
    SELECT @v, x.c, x.n, x.m, x.r, x.col, x.t FROM (VALUES
        (N'LOW', N'Low', 0, 1, N'#16a34a', N'BASIC'),
        (N'MODERATE', N'Moderate', 30, 2, N'#ca8a04', N'STANDARD'),
        (N'HIGH', N'High', 50, 3, N'#ea580c', N'ENHANCED'),
        (N'CRITICAL', N'Critical', 70, 4, N'#dc2626', N'ENHANCED')
    ) x(c, n, m, r, col, t);
    INSERT grac_practice.tprm_rm_tier_rule (version_id, condition_kind, condition_code, min_dd_tier_code)
    SELECT @v, x.k, x.c, x.t FROM (VALUES
        (N'CRITICALITY', N'CRITICAL', N'ENHANCED'),
        (N'CRITICALITY', N'HIGH', N'STANDARD'),
        (N'DATA_EXPOSURE', N'PERSONAL', N'STANDARD'),
        (N'DATA_EXPOSURE', N'SENSITIVE_PERSONAL', N'ENHANCED'),
        (N'DATA_EXPOSURE', N'PAYMENT', N'ENHANCED'),
        (N'DATA_EXPOSURE', N'REGULATED_FINANCIAL', N'ENHANCED'),
        (N'ACCESS', N'PRIVILEGED', N'ENHANCED'),
        (N'ACCESS', N'DATA_HOSTING', N'STANDARD')
    ) x(k, c, t);
    COMMIT;
    PRINT '487: risk model GRAC_TPRM_STANDARD v1 created.';
END
ELSE PRINT '487: risk model GRAC_TPRM_STANDARD already present -- published versions are never rewritten.';
GO

-- =====================================================================
-- 6. Due-diligence questionnaires (core, enhanced, six service-specific)
-- =====================================================================
IF NOT EXISTS (SELECT 1 FROM grac_practice.tprm_template
                WHERE organization_id IS NULL AND template_kind = N'QUESTIONNAIRE' AND template_code = N'GRAC_DD_CORE')
BEGIN
    DECLARE @t BIGINT, @v BIGINT;
    BEGIN TRAN;
    INSERT grac_practice.tprm_template (organization_id, template_kind, template_code, template_name, description, status, entered_by)
    VALUES (NULL, N'QUESTIONNAIRE', N'GRAC_DD_CORE', N'Core due-diligence questionnaire', N'Generated for every engagement. Conditional follow-ups appear only when relevant.', N'Active', N'seed-487');
    SET @t = SCOPE_IDENTITY();
    INSERT grac_practice.tprm_template_version
        (template_id, version_no, status, change_summary, is_core, applies_service_categories, applies_min_tier_rank, created_by, activated_by, activated_dt)
    VALUES (@t, 1, N'ACTIVE', N'GRAC baseline version 1', 1, NULL, NULL, N'seed-487', N'seed-487', SYSUTCDATETIME());
    SET @v = SCOPE_IDENTITY();
    UPDATE grac_practice.tprm_template SET current_version_id = @v WHERE template_id = @t;
    INSERT grac_practice.tprm_q_section (version_id, section_code, title, display_order)
    SELECT @v, x.c, x.t, x.o FROM (VALUES
        (N'GOV', N'Governance and organizational profile', 10),
        (N'INFOSEC', N'Information security', 20),
        (N'PRIVACY', N'Data protection', 30),
        (N'RESILIENCE', N'Business continuity and resilience', 40),
        (N'SUBCON', N'Subcontracting and fourth parties', 50),
        (N'COMPLIANCE', N'Compliance and insurance', 60)
    ) x(c, t, o);
    INSERT grac_practice.tprm_q_question
        (version_id, section_id, question_code, question_text, guidance, response_type, is_mandatory, evidence_expected,
         evidence_requirement_code, safeguard_code, dimension_code, min_tier_rank, applies_service_categories, applies_min_data_rank,
         applies_access_codes, parent_question_code, trigger_option_codes, weight, display_order, source_authority, source_document,
         source_version, source_reference, applicability_note, is_regulatory)
