        (N'KY5', N'NA', N'Not applicable', NULL, 0, NULL, 30)
    ) x(qc, c, l, s, f, sev, o)
    JOIN grac_practice.tprm_q_question qq ON qq.version_id = @v AND qq.question_code = x.qc;
    COMMIT;
    PRINT '487: questionnaire GRAC_DD_KYC v1 created.';
END
ELSE PRINT '487: questionnaire GRAC_DD_KYC already present -- not rewritten.';
GO

-- =====================================================================
-- 7. Sample profiles (BRD 5.2). Clearly marked SAMPLE / Example; loaded
--    into an organization only on request (sp_tprm_sample_load, 488).
-- =====================================================================
MERGE grac_practice.tprm_sample_profile AS t
USING (VALUES
    (N'SAMPLE_CLOUD', N'SAMPLE - Example Cloud Hosting Provider', N'COMPANY', N'CLOUD_HOSTING', N'India', N'Example: Production hosting of the customer portal', N'Illustrative example - infrastructure hosting (IaaS) for the customer-facing portal and its databases.', N'Compute, storage, managed database and backup in two regions.', N'Scalable, resilient hosting for the customer portal.', N'IAAS', N'NEW_SERVICE', N'CRITICAL', N'PERSONAL', N'DATA_HOSTING,PRIVILEGED', 4, 1, N'Example Data Centre Operator|HOSTING|India;Example CDN Provider|CONNECTIVITY|Singapore', N'SG_SEC_ATTESTATION,SG_ENCRYPTION,SG_DATA_LOCATION,SG_BCP,SG_BACKUP,SG_EXIT_PLAN,SG_AUDIT_RIGHTS', N'SEC_CERT,SOC2_REPORT,BCP_TEST_REPORT,DPA', N'INCIDENT,LOCATION_CHANGE,FOURTH_PARTY_CHANGE,CERTIFICATION_EXPIRY', N'Demonstrates a critical, data-hosting engagement in the Enhanced tier.', 10),
    (N'SAMPLE_APPDEV', N'SAMPLE - Example Application Development Partner', N'COMPANY', N'APP_DEV_MAINT', N'India', N'Example: Development and maintenance of the lending platform', N'Illustrative example - custom development and L3 support of an internal application.', N'Feature development, bug fixes, release management; no production data in test.', N'Accelerate delivery of the lending platform roadmap.', N'OFFSHORE', N'ONGOING', N'HIGH', N'CONFIDENTIAL', N'REMOTE_USER,SYSTEM_INTEGRATION', 24, 4, N'Example Contract Developers|SUBCONTRACTED_STAFF|India', N'SG_SECURE_SDLC,SG_CHANGE_MGMT,SG_ACCESS_CONTROL,SG_CONFIDENTIALITY,SG_PERSONNEL_SCREENING', N'PENTEST_REPORT,BACKGROUND_CHECK,SEC_POLICIES', N'SCOPE_CHANGE,INCIDENT,FOURTH_PARTY_CHANGE', N'Demonstrates source-code ownership and secure development questions.', 20),
    (N'SAMPLE_MSSP', N'SAMPLE - Example Managed Security Service Provider', N'COMPANY', N'MANAGED_IT_SECURITY', N'India', N'Example: 24x7 security monitoring (SOC)', N'Illustrative example - managed detection and response with privileged access to security tools.', N'Log collection, monitoring, triage and incident escalation.', N'Round-the-clock threat detection.', N'MANAGED_SERVICE', N'NEW_SERVICE', N'CRITICAL', N'CONFIDENTIAL', N'PRIVILEGED,NETWORK', 2, 1, N'Example SIEM Platform|SOFTWARE_COMPONENT|United States;Example Threat Intel Feed|VERIFICATION_SOURCE|United Kingdom', N'SG_ACCESS_CONTROL,SG_LOGGING_MONITORING,SG_INCIDENT_NOTIFICATION,SG_SEC_ATTESTATION,SG_SUBCONTRACTING', N'SEC_CERT,SOC2_REPORT,BACKGROUND_CHECK', N'INCIDENT,SLA_BREACH,FOURTH_PARTY_CHANGE,ASSURANCE_FAILURE', N'Demonstrates privileged-access and fourth-party (tooling) exposure.', 30),
    (N'SAMPLE_PAYMENT', N'SAMPLE - Example Payment Gateway', N'COMPANY', N'PAYMENT_API', N'India', N'Example: Online payment collection via API', N'Illustrative example - payment gateway integration for customer collections.', N'Card, UPI and net-banking collections; settlement; refunds; reconciliation files.', N'Digital collections for customers.', N'SAAS', N'NEW_SERVICE', N'HIGH', N'PAYMENT', N'SYSTEM_INTEGRATION', 4, 0, N'Example Card Network|PAYMENT_NETWORK|Global;Example Acquiring Bank|PAYMENT_NETWORK|India', N'SG_PCI,SG_LICENSING,SG_ACCESS_CONTROL,SG_INCIDENT_NOTIFICATION,SG_SLA', N'PCI_AOC,LICENCE,SLA_REPORT', N'INCIDENT,SLA_BREACH,CERTIFICATION_EXPIRY', N'Demonstrates payment card data and regulatory licensing.', 40),
    (N'SAMPLE_PAYROLL', N'SAMPLE - Example HR and Payroll Bureau', N'COMPANY', N'HR_PAYROLL', N'India', N'Example: Monthly payroll processing', N'Illustrative example - outsourced payroll calculation, payslips and statutory filings.', N'Payroll for all employees, statutory deductions, payslips, year-end forms.', N'Accurate, compliant payroll.', N'SAAS', N'ONGOING', N'HIGH', N'SENSITIVE_PERSONAL', N'REMOTE_USER,DATA_HOSTING', 24, 24, N'Example Cloud Payroll Platform|HOSTING|India', N'SG_DPA,SG_DATA_MINIMISATION,SG_BCP,SG_ACCESS_CONTROL,SG_DATA_RETURN_DELETION', N'DPA,SEC_CERT,BCP_TEST_REPORT', N'INCIDENT,DATA_ACCESS_CHANGE,CONTRACT_RENEWAL', N'Demonstrates sensitive employee personal data.', 50),
    (N'SAMPLE_KYC', N'SAMPLE - Example KYC Processing Service', N'COMPANY', N'KYC_DOC_PROCESSING', N'India', N'Example: Customer KYC verification', N'Illustrative example - verification of customer identity documents for onboarding.', N'Document capture, verification, liveness checks and record retention.', N'Faster, compliant customer onboarding.', N'MANAGED_SERVICE', N'NEW_SERVICE', N'HIGH', N'SENSITIVE_PERSONAL', N'SYSTEM_INTEGRATION,DATA_HOSTING', 8, 4, N'Example ID Verification Source|VERIFICATION_SOURCE|India;Example Document Storage|HOSTING|India', N'SG_DPA,SG_DATA_LOCATION,SG_DATA_MINIMISATION,SG_REG_REPORTING,SG_PERFORMANCE_GOVERNANCE', N'DPA,SEC_CERT,LICENCE', N'INCIDENT,LOCATION_CHANGE,FOURTH_PARTY_CHANGE', N'Demonstrates regulated customer data with verification fourth parties.', 60)
) AS s(sample_code, legal_name, provider_type_code, service_category_code, country, engagement_title, service_description,
       scope_description, business_purpose, service_model_code, engagement_type_code, criticality_code, data_exposure_code,
       access_codes, rto_hours, rpo_hours, fourth_parties, key_safeguards, evidence_expectations, review_triggers, notes, display_order)
ON t.sample_code = s.sample_code
WHEN MATCHED THEN UPDATE SET legal_name = s.legal_name, provider_type_code = s.provider_type_code,
    service_category_code = s.service_category_code, country = s.country, engagement_title = s.engagement_title,
    service_description = s.service_description, scope_description = s.scope_description, business_purpose = s.business_purpose,
    service_model_code = s.service_model_code, engagement_type_code = s.engagement_type_code, criticality_code = s.criticality_code,
    data_exposure_code = s.data_exposure_code, access_codes = s.access_codes, rto_hours = s.rto_hours, rpo_hours = s.rpo_hours,
    fourth_parties = s.fourth_parties, key_safeguards = s.key_safeguards, evidence_expectations = s.evidence_expectations,
    review_triggers = s.review_triggers, notes = s.notes, display_order = s.display_order
WHEN NOT MATCHED BY TARGET THEN INSERT
    (sample_code, legal_name, provider_type_code, service_category_code, country, engagement_title, service_description,
     scope_description, business_purpose, service_model_code, engagement_type_code, criticality_code, data_exposure_code,
     access_codes, rto_hours, rpo_hours, fourth_parties, key_safeguards, evidence_expectations, review_triggers, notes, display_order)
    VALUES (s.sample_code, s.legal_name, s.provider_type_code, s.service_category_code, s.country, s.engagement_title, s.service_description,
     s.scope_description, s.business_purpose, s.service_model_code, s.engagement_type_code, s.criticality_code, s.data_exposure_code,
     s.access_codes, s.rto_hours, s.rpo_hours, s.fourth_parties, s.key_safeguards, s.evidence_expectations, s.review_triggers, s.notes,
     s.display_order);
PRINT CONCAT('487: sample profiles merged: ', @@ROWCOUNT);
GO

-- =====================================================================
-- 8. Verification
-- =====================================================================
SELECT '487 reference lists and values' AS Check_,
       CASE WHEN (SELECT COUNT(*) FROM grac_practice.tprm_reference_list) >= 19
             AND (SELECT COUNT(*) FROM grac_practice.tprm_reference_value WHERE organization_id IS NULL) >= 120
            THEN 'PASS' ELSE 'FAIL' END AS Result_
UNION ALL
SELECT '487 every MEANING value maps to an allowed meaning',
       CASE WHEN NOT EXISTS (SELECT 1 FROM grac_practice.tprm_reference_value v
                              JOIN grac_practice.tprm_reference_list l ON l.list_code = v.list_code
                              WHERE l.scope_rule = N'MEANING'
                                AND NOT EXISTS (SELECT 1 FROM grac_practice.fn_tprm_split_codes(l.allowed_meanings) m
                                                 WHERE m.code = v.meaning_code))
            THEN 'PASS' ELSE 'FAIL' END
UNION ALL
SELECT '487 library (safeguards / evidence / treatment)',
       CASE WHEN (SELECT COUNT(*) FROM grac_practice.tprm_library_item WHERE organization_id IS NULL AND library_code = N'SAFEGUARD') >= 30
             AND (SELECT COUNT(*) FROM grac_practice.tprm_library_item WHERE organization_id IS NULL AND library_code = N'EVIDENCE_REQUIREMENT') >= 12
             AND (SELECT COUNT(*) FROM grac_practice.tprm_library_item WHERE organization_id IS NULL AND library_code = N'TREATMENT_ACTION') >= 8
            THEN 'PASS' ELSE 'FAIL' END
UNION ALL
SELECT '487 no baseline row claims to be regulatory',
       CASE WHEN NOT EXISTS (SELECT 1 FROM grac_practice.tprm_library_item WHERE organization_id IS NULL AND is_regulatory = 1)
             AND NOT EXISTS (SELECT 1 FROM grac_practice.tprm_q_question q
                              JOIN grac_practice.tprm_template_version v ON v.version_id = q.version_id
                              JOIN grac_practice.tprm_template t ON t.template_id = v.template_id
                              WHERE t.organization_id IS NULL AND q.is_regulatory = 1)
            THEN 'PASS' ELSE 'FAIL' END
UNION ALL
SELECT '487 risk model: 8 dimensions, every factor >= 2 options, band at 0',
       CASE WHEN (SELECT COUNT(*) FROM grac_practice.tprm_rm_dimension d
                   JOIN grac_practice.tprm_template t ON t.current_version_id = d.version_id
                   WHERE t.organization_id IS NULL AND t.template_code = N'GRAC_TPRM_STANDARD') = 8
             AND NOT EXISTS (SELECT 1 FROM grac_practice.tprm_rm_factor f
                              JOIN grac_practice.tprm_template t ON t.current_version_id = f.version_id
                              WHERE t.template_code = N'GRAC_TPRM_STANDARD' AND t.organization_id IS NULL
                                AND (SELECT COUNT(*) FROM grac_practice.tprm_rm_factor_option o WHERE o.factor_id = f.factor_id) < 2)
             AND EXISTS (SELECT 1 FROM grac_practice.tprm_rm_band b
                          JOIN grac_practice.tprm_template t ON t.current_version_id = b.version_id
                          WHERE t.template_code = N'GRAC_TPRM_STANDARD' AND t.organization_id IS NULL AND b.min_score = 0)
            THEN 'PASS' ELSE 'FAIL' END
UNION ALL
SELECT '487 eight questionnaires active, follow-ups resolve',
       CASE WHEN (SELECT COUNT(*) FROM grac_practice.tprm_template
                   WHERE organization_id IS NULL AND template_kind = N'QUESTIONNAIRE' AND current_version_id IS NOT NULL) >= 8
             AND NOT EXISTS (SELECT 1 FROM grac_practice.tprm_q_question q
                              WHERE q.parent_question_code IS NOT NULL
                                AND NOT EXISTS (SELECT 1 FROM grac_practice.tprm_q_question p
                                                 WHERE p.version_id = q.version_id AND p.question_code = q.parent_question_code))
            THEN 'PASS' ELSE 'FAIL' END
UNION ALL
SELECT '487 approval and review rules',
       CASE WHEN (SELECT COUNT(*) FROM grac_practice.tprm_approval_rule WHERE organization_id IS NULL) >= 4
             AND (SELECT COUNT(*) FROM grac_practice.tprm_review_rule WHERE organization_id IS NULL) >= 4
            THEN 'PASS' ELSE 'FAIL' END
UNION ALL
SELECT '487 six sample profiles',
       CASE WHEN (SELECT COUNT(*) FROM grac_practice.tprm_sample_profile) >= 6 THEN 'PASS' ELSE 'FAIL' END;
GO

PRINT '487 complete. Run 488_tprm_third_parties_engagements.sql next.';
GO
